    "Salary and hourly pay": "الراتب والأجر بالساعة",
    "Pay by the hour, day, week, month or year, in each of the others, of the hours and days worked a week and the weeks a year; with overtime a week at so many times the hourly if you like.": "الأجر بالساعة أو اليوم أو الأسبوع أو الشهر أو السنة، محوَّلًا إلى كل من الأخرى، حسب ساعات العمل وأيامه في الأسبوع وأسابيعه في السنة؛ مع ساعات عمل إضافي أسبوعية بأضعاف أجر الساعة إن شئت.",
