    "Overtime, times the hourly": "العمل الإضافي، أضعاف أجر الساعة",
    "Interest rates": "معدلات الفائدة",
    "A nominal rate a year, its APR, as the effective one, its APY, of interest m times a year, and back: type one, and the other is worked out. m may be ∞, typed inf, for interest all the time.": "المعدل الاسمي السنوي APR والمعدل الفعلي APY، لفائدة تُضاف m مرة في السنة، والتحويل بينهما: اكتب أحدهما ليُحسب الآخر. يمكن أن تكون m هي ∞، وتُكتب inf، لفائدة مستمرة.",
    "APY %": "APY %",
    "Break-even": "نقطة التعادل",
    "How many must be sold to cover the fixed costs, and a profit if you like, at a price and a cost of each one: the units, what they sell for, and what each one leaves.": "عدد الوحدات التي يجب بيعها لتغطية التكاليف الثابتة، مع ربح إن شئت، بسعر وتكلفة معينين للوحدة: عدد الوحدات، وإيراد بيعها، وما تتركه كل وحدة.",
    "Fixed costs": "التكاليف الثابتة",
    "Cost each": "تكلفة الوحدة",
    "Profit": "الربح",
    "Inflation": "التضخم",
    "An amount at inflation of a rate a year for years: what it costs then, what it was worth in money of today, how many times prices grow, and how much of what money buys is lost.": "مبلغ مع تضخم بمعدل سنوي لعدد من السنوات: كم سيكلف حينها، وكم كانت قيمته بأموال اليوم، وكم مرة تتضاعف الأسعار، وكم تفقد النقود من قوتها الشرائية.",
    "Amount": "المبلغ",
    "Depreciation": "الإهلاك",
    "What an asset loses each year of its life, down to what it is worth at the end, its salvage value: the same each year by the straight line, or twice the straight line's rate of what is left by the double declining balance, then the straight line once that loses more. A table of each year; Copy table copies it for a spreadsheet.": "ما يفقده الأصل كل سنة من عمره حتى قيمته في النهاية، أي قيمته المتبقية: المقدار نفسه كل سنة بطريقة القسط الثابت، أو ضعف معدل القسط الثابت من الرصيد المتبقي بطريقة الرصيد المتناقص المضاعف، ثم القسط الثابت حين يصبح إهلاكه أكبر. مع جدول لكل سنة؛ يَنسخ «نسخ الجدول» الجدول للصقه في جدول بيانات.",
    "Cost": "التكلفة",
    "Salvage": "القيمة المتبقية",
    "Way": "الطريقة",
    "Straight line": "القسط الثابت",
    "Declining balance": "الرصيد المتناقص",
    "Time value of money": "القيمة الزمنية للنقود",
    "Money over time, as a BA II Plus or an HP 12C works it out: leave one of N, I/Y, PV, PMT and FV empty, and it is worked out. N payments of PMT, at I/Y, a percentage a year, of P/Y payments a year, bring PV at the start to FV at the end; each payment at the end of its period, or at its start. Money received is above 0 and money paid below 0: a loan of 200000 is PV = 200000, its PMT below 0. With all the money paid, and the interest.": "المال عبر الزمن كما تحسبه آلة BA II Plus أو HP 12C: اترك أحد الحقول N وI/Y وPV وPMT وFV فارغًا ليُحسب. ‏N دفعة قيمة كل منها PMT، بمعدل I/Y سنويًا كنسبة مئوية، بعدد P/Y دفعة في السنة، تنقل PV في البداية إلى FV في النهاية؛ كل دفعة في نهاية فترتها أو في بدايتها. المال المقبوض موجب والمدفوع سالب: قرض قيمته 200000 هو PV = 200000، وPMT سالبة. مع مجموع المدفوع والفوائد.",
    "PV": "PV",
    "PMT": "PMT",
    "FV": "FV",
    "Payments": "الدفعات",
    "NPV and IRR": "صافي القيمة الحالية ومعدل العائد الداخلي",
    "Of cash flows, one a period, the first at the start and usually below 0, as it is paid out: their net present value at the rate r, a percentage a period; their internal rate of return, the rate of an NPV of 0; and how many periods they take to pay back what went out. Type the flows one to a line, or apart as the statistics list is: -1000, 300, 400, 500.": "لتدفقات نقدية، واحد لكل فترة، أولها في البداية وعادةً سالب لأنه مدفوع: صافي قيمتها الحالية بالمعدل r كنسبة مئوية لكل فترة؛ ومعدل العائد الداخلي، وهو المعدل الذي يجعل صافي القيمة الحالية صفرًا؛ وعدد الفترات اللازمة لاسترداد ما دُفع. اكتب التدفقات واحدًا في كل سطر، أو مفصولة كما في قائمة الإحصاء: ‎-1000, 300, 400, 500.",
    "Cash flows": "التدفقات النقدية",
    "Bond price and yield": "سعر السند وعائده",
    "A bond of a face value paying its coupon, a percentage of it a year, in parts a number of times a year, for years: leave one of Price and Yield empty, and it is worked out, the yield a year as a BA II Plus gives it. Years that are not whole coupons bring the next coupon nearer: the price is then without the interest earned since the last one, the accrued interest, and the dirty price with it. With the current yield and the duration.": "سند بقيمة اسمية يدفع كوبونه، نسبة مئوية منها سنويًا، على دفعات عدة مرات في السنة، لعدد من السنوات: اترك أحد الحقلين «السعر» و«العائد» فارغًا ليُحسب، والعائد السنوي كما تعطيه BA II Plus. السنوات التي لا تكتمل فيها الكوبونات تقرّب الكوبون التالي: فيكون السعر دون الفائدة المكتسبة منذ آخر كوبون، أي الفائدة المستحقة، والسعر الإجمالي شاملًا إياها. مع العائد الجاري والمدة.",
    "Face": "القيمة الاسمية",
    "Coupon %": "الكوبون %",
    "Coupons a year": "الكوبونات في السنة",
    "Yield %": "العائد %",
    "Percentage change": "نسبة التغير",
    "The change from one number to another, and as a percentage of the first; of a cost and its price, the first is the markup and the margin the profit as a percentage of the price.": "التغير من عدد إلى آخر، وكنسبة مئوية من الأول؛ ولتكلفة وسعر بيع، الأولى هي نسبة الربح على التكلفة، والهامش هو الربح كنسبة من سعر البيع.",
    "Tip and split": "البقشيش وتقسيم الفاتورة",
    "A bill and a tip, a percentage of it: the tip, the total, and what each pays, split among people; rounded up so each pays a whole amount, or the total is, if you like.": "فاتورة وبقشيش بنسبة منها: قيمة البقشيش، والإجمالي، ونصيب كل شخص عند التقسيم؛ مع التقريب للأعلى ليدفع كل شخص مبلغًا صحيحًا، أو ليكون الإجمالي كذلك، إن شئت.",
    "Bill": "الفاتورة",
