    "Fuel cost": "تكلفة الوقود",
    "The fuel a trip takes, of a car's economy in L/100 km, km a litre or miles a gallon, US or UK, and what it costs at a price of fuel: a km or a mile as well, there and back, and what each pays, split among people; with the economy the other way.": "الوقود الذي تستهلكه رحلة، حسب استهلاك السيارة باللتر لكل 100 كم أو الكيلومترات لكل لتر أو الأميال لكل غالون أمريكي أو بريطاني، وتكلفته بسعر وقود معين: لكل كيلومتر أو ميل أيضًا، ذهابًا وإيابًا، ونصيب كل شخص عند التقسيم؛ مع الاستهلاك بالصيغة الأخرى.",
