    "The second date is before the first: the numbers are below 0.": "التاريخ الثاني قبل الأول: الأعداد سالبة.",
    "Weekdays are Monday to Friday, both dates in.": "أيام العمل من الاثنين إلى الجمعة، شاملة التاريخين.",
