    "Punnett square": "",
    "The offspring of two parents, of one gene or up to six: each genotype typed as it is written, Aa or AaBbCc, a capital for the dominant allele. Their gametes, the square drawn and coloured by phenotype, and the ratios of the phenotypes and genotypes, drawn. Incomplete: a capital and a small letter show between the two, as red and white snapdragons give pink.": "",
