    "Sex-linked cross": "",
    "A gene on the X chromosome, as of colour blindness or haemophilia: the mother's two alleles, as XAXa, and the father's one, as XaY; the square drawn, and the chances of each phenotype among the daughters, among the sons and of all the children.": "",
