    "Father": "",
    "Hardy–Weinberg": "",
    "A gene of two alleles in a population mating at random: of p, the frequency of the dominant allele; of the counts of the three genotypes, with a χ² test of whether they are at equilibrium; or of how many show the recessive trait, as 1/2500, how many are carriers. Its three curves drawn, p², 2pq and q².": "",
